# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.79.0/ankra-cli-darwin-arm64"
      sha256 "bf5a860338cfde7e6664c7f63812f06671adfc4810e4b33256538c6ee59c00a0"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.79.0/ankra-cli-darwin-amd64"
      sha256 "2f13d058abd4b9dd53b7fe909a490e6b4cdf8a8bbe3d9b0601c3da5d5c9a3abf"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.79.0/ankra-cli-linux-arm64"
      sha256 "220dc6ed0b9feaae8d4ffcda78dc58d6f1f3155b691222e5992025e55adf2168"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.79.0/ankra-cli-linux-amd64"
